try {
  const entrada = $input.first().json;
  const esperado = $env.ADORBIT_N8N_WEBHOOK_TOKEN || 'token-webhook-local';
  const recibido = (entrada.headers || {})['x-webhook-token'];
  const fallo = (estado_http, codigo, mensaje, detalle) => [{
    json: {
      ok: false,
      estado_http,
      respuesta: { codigo, mensaje, detalle: detalle || null }
    }
  }];

  if (!recibido || recibido !== esperado) {
    return fallo(401, 'no_autenticado', 'Falta o es invalido el encabezado X-Webhook-Token');
  }

  const b = entrada.body || {};
  if (!b.titulo || typeof b.titulo !== 'string' || b.titulo.trim() === '') {
    return fallo(400, 'solicitud_invalida', 'El campo titulo es obligatorio');
  }

  const tipo = (b.tipo || 'general').toLowerCase();
  const tel = b.destinatario_whatsapp || $env.ADORBIT_WHATSAPP_NUMERO_GERENCIA || '+59169215158';
  const email = b.destinatario_email || $env.ADORBIT_CORREO_GERENCIA || 'hebertsuarezb@gmail.com';
  const enlace = b.enlace_accion || 'http://localhost:4200';
  const fechaHora = new Date().toLocaleString('es-BO', { timeZone: 'America/La_Paz' });

  function corregirEspanol(str) {
    if (!str || typeof str !== 'string') return str;
    return str
      .replace(/\bcampana\b/gi, (m) => m === 'campana' ? 'campaña' : (m === 'CAMPANA' ? 'CAMPAÑA' : 'Campaña'))
      .replace(/\bcampanas\b/gi, (m) => m === 'campanas' ? 'campañas' : (m === 'CAMPANAS' ? 'CAMPAÑAS' : 'Campañas'))
      .replace(/\bdiseno\b/gi, (m) => m === 'diseno' ? 'diseño' : (m === 'DISENO' ? 'DISEÑO' : 'Diseño'))
      .replace(/\bdisenos\b/gi, (m) => m === 'disenos' ? 'diseños' : (m === 'DISENOS' ? 'DISEÑOS' : 'Diseños'))
      .replace(/\banalisis\b/gi, (m) => m === 'analisis' ? 'análisis' : (m === 'ANALISIS' ? 'ANÁLISIS' : 'Análisis'))
      .replace(/\bauditoria\b/gi, (m) => m === 'auditoria' ? 'auditoría' : (m === 'AUDITORIA' ? 'AUDITORÍA' : 'Auditoría'))
      .replace(/\bvision\b/gi, (m) => m === 'vision' ? 'visión' : (m === 'VISION' ? 'VISIÓN' : 'Visión'))
      .replace(/\bclasificacion\b/gi, (m) => m === 'clasificacion' ? 'clasificación' : (m === 'CLASIFICACION' ? 'CLASIFICACIÓN' : 'Clasificación'))
      .replace(/\bconfiguracion\b/gi, (m) => m === 'configuracion' ? 'configuración' : (m === 'CONFIGURACION' ? 'CONFIGURACIÓN' : 'Configuración'))
      .replace(/\bejecucion\b/gi, (m) => m === 'ejecucion' ? 'ejecución' : (m === 'EJECUCION' ? 'EJECUCIÓN' : 'Ejecución'))
      .replace(/\bejecuciones\b/gi, (m) => m === 'ejecuciones' ? 'ejecuciones' : (m === 'EJECUCIONES' ? 'EJECUCIONES' : 'Ejecuciones'))
      .replace(/\bvalidacion\b/gi, (m) => m === 'validacion' ? 'validación' : (m === 'VALIDACION' ? 'VALIDACIÓN' : 'Validación'))
      .replace(/\bdescripcion\b/gi, (m) => m === 'descripcion' ? 'descripción' : (m === 'DESCRIPCION' ? 'DESCRIPCIÓN' : 'Descripción'))
      .replace(/\binversion\b/gi, (m) => m === 'inversion' ? 'inversión' : (m === 'INVERSION' ? 'INVERSIÓN' : 'Inversión'))
      .replace(/\bduracion\b/gi, (m) => m === 'duracion' ? 'duración' : (m === 'DURACION' ? 'DURACIÓN' : 'Duración'))
      .replace(/\bnumero\b/gi, (m) => m === 'numero' ? 'número' : (m === 'NUMERO' ? 'NÚMERO' : 'Número'))
      .replace(/\btelefono\b/gi, (m) => m === 'telefono' ? 'teléfono' : (m === 'TELEFONO' ? 'TELÉFONO' : 'Teléfono'))
      .replace(/\bevaluacion\b/gi, (m) => m === 'evaluacion' ? 'evaluación' : (m === 'EVALUACION' ? 'EVALUACIÓN' : 'Evaluación'))
      .replace(/\bano\b/gi, (m) => m === 'ano' ? 'año' : (m === 'ANO' ? 'AÑO' : 'Año'))
      .replace(/\banos\b/gi, (m) => m === 'anos' ? 'años' : (m === 'ANOS' ? 'AÑOS' : 'Años'))
      .replace(/\btamano\b/gi, (m) => m === 'tamano' ? 'tamaño' : (m === 'TAMANO' ? 'TAMAÑO' : 'Tamaño'))
      .replace(/\bkpis\b/gi, 'KPIs')
      .replace(/\bctr\b/gi, 'CTR')
      .replace(/\bcpc\b/gi, 'CPC')
      .replace(/\bcpa\b/gi, 'CPA')
      .replace(/\broas\b/gi, 'ROAS');
  }

  const DICCIONARIO_ETIQUETAS = {
    campana: 'Campaña',
    campana_nombre: 'Campaña',
    campaña: 'Campaña',
    nombre_campana: 'Campaña',
    nombre_campaña: 'Campaña',
    campana_id: 'ID Campaña',
    campaña_id: 'ID Campaña',
    id_campana: 'ID Campaña',
    id_campaña: 'ID Campaña',
    kpis: 'KPIs',
    ctr: 'CTR',
    cpc: 'CPC',
    cpa: 'CPA',
    roas: 'ROAS',
    calidad: 'Índice de Calidad',
    indice_calidad: 'Índice de Calidad',
    estado: 'Estado',
    inversion: 'Inversión',
    presupuesto: 'Presupuesto',
    descripcion: 'Descripción',
    diseno: 'Diseño',
    diseño: 'Diseño',
    categoria: 'Categoría',
    creacion: 'Creación',
    duracion: 'Duración',
    duracion_ms: 'Duración (ms)',
    numero: 'Número',
    telefono: 'Teléfono',
    ejecucion_id: 'ID Ejecución',
    agente_id: 'ID Agente',
    pieza_id: 'ID Pieza Gráfica',
    detecta_logo: 'Detección de Marca',
    confianza: 'Nivel de Confianza',
    manual_marca: 'Manual de Marca',
    objetos: 'Objetos Detectados',
    hallazgos: 'Hallazgos Clave'
  };

  const MAPA_REFERENCIAS = {
    auditoria_vision: 'AUDITORÍA DE VISIÓN',
    analisis_ia: 'ANÁLISIS DE INTELIGENCIA ARTIFICIAL',
    alerta_campana: 'ALERTA DE CAMPAÑA',
    alerta_optimizacion: 'ALERTA DE OPTIMIZACIÓN',
    factura_emitida: 'FACTURA EMITIDA',
    cobranza: 'GESTIÓN DE COBRANZA',
    general: 'COMUNICADO CORPORATIVO'
  };

  const refTipo = MAPA_REFERENCIAS[tipo] || corregirEspanol(tipo.replace(/_/g, ' ')).toUpperCase();

  let lineasDetalle = [];
  let filasHtml = '';
  const objDatos = b.datos || b.kpis || b.metricas || {};
  if (objDatos && typeof objDatos === 'object') {
    for (const [k, v] of Object.entries(objDatos)) {
      if (v !== null && v !== undefined && typeof v !== 'object') {
        const claveNorm = k.toLowerCase().replace(/[\s\-]+/g, '_').trim();
        const etiqueta = DICCIONARIO_ETIQUETAS[claveNorm] || corregirEspanol(k.replace(/_/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase()));
        const valorLimpio = corregirEspanol(String(v));
        lineasDetalle.push(`▪ *${etiqueta}:* ${valorLimpio}`);
        filasHtml += `<tr><td style="padding:8px 12px;font-weight:600;color:#334155;border-bottom:1px solid #f1f5f9;font-size:13px;width:38%;">${etiqueta}</td><td style="padding:8px 12px;color:#0f172a;border-bottom:1px solid #f1f5f9;font-size:13px;">${valorLimpio}</td></tr>`;
      }
    }
  }

  const tituloLimpio = corregirEspanol(b.titulo.trim());

  const msgWhatsapp = `🏛️ *ADORBIT ENTERPRISE · REPORTE EJECUTIVO*\n` +
    `────────────────────────────────────────\n` +
    `📋 *Asunto:* ${tituloLimpio}\n` +
    `📅 *Fecha:* ${fechaHora}\n` +
    `🏷️ *Referencia:* ${refTipo} / ADORBIT-2026\n\n` +
    `*RESUMEN EJECUTIVO Y MÉTRICAS:*\n` +
    (lineasDetalle.length ? lineasDetalle.join('\n') + '\n' : '▪ Sin parámetros adicionales\n') +
    `────────────────────────────────────────\n` +
    `Consulte los detalles y métricas completas en la plataforma:\n` +
    `🌐 ${enlace}\n\n` +
    `*AdOrbit Platform · Dirección de Inteligencia y Operaciones*`;

  const BANNER_OFICIAL_URL = 'https://gbsxuruxkowamugicucb.supabase.co/storage/v1/object/public/piezas-creatividades/banner-adorbit-whatsapp.png';
  const imgWhatsapp = (b.datos && (b.datos.imagen_url || b.datos.imagen)) || b.imagen_url || b.imagen || BANNER_OFICIAL_URL;

  const logoSvg = '<svg width="32" height="32" viewBox="0 0 128 128" fill="none" xmlns="http://www.w3.org/2000/svg" style="vertical-align:middle;display:inline-block;"><path d="M25 104 L57 25 Q59 20 65 20 L69 20 Q74 20 76 25 L108 104 L86 104 L65 48 L45 104 Z" fill="#4f46e5"/><path d="M103 37 C80 31 38 48 19 69 C-2 92 21 102 58 91 C80 85 100 74 111 62 L105 57 C91 70 72 79 54 84 C26 92 16 87 28 75 C44 58 80 43 100 44 Z" fill="#4f46e5"/><circle cx="110" cy="39" r="8" fill="#4f46e5"/></svg>';

  const htmlCorreo = `<div style="background-color:#f1f5f9;padding:28px 12px;margin:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased;">\n` +
    `<div style="max-width:580px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;box-shadow:0 10px 15px -3px rgba(0,0,0,0.07);">\n` +
    `  <div style="padding:20px 26px;background:#ffffff;border-bottom:1px solid #f1f5f9;">\n` +
    `    <table width="100%" cellpadding="0" cellspacing="0" border="0">\n` +
    `      <tr>\n` +
    `        <td style="vertical-align:middle;">\n` +
    `          ${logoSvg}\n` +
    `          <span style="font-size:21px;font-weight:800;color:#0f172a;letter-spacing:-0.5px;margin-left:8px;vertical-align:middle;">AdOrbit</span>\n` +
    `        </td>\n` +
    `        <td align="right" style="vertical-align:middle;">\n` +
    `          <span style="display:inline-block;background:#eef2ff;color:#4f46e5;font-size:11px;font-weight:700;padding:4px 10px;border-radius:20px;letter-spacing:0.5px;text-transform:uppercase;">Alerta IA & Notificación</span>\n` +
    `        </td>\n` +
    `      </tr>\n` +
    `    </table>\n` +
    `  </div>\n` +
    `  <div style="height:3px;background:linear-gradient(90deg,#4f46e5 0%,#818cf8 100%);"></div>\n` +
    `  <div style="padding:28px 26px;color:#1e293b;font-size:14px;line-height:1.65;">\n` +
    `    <h2 style="font-size:19px;font-weight:700;color:#0f172a;margin:0 0 16px 0;letter-spacing:-0.3px;">${tituloLimpio}</h2>\n` +
    `    <p style="margin:0 0 16px 0;color:#475569;">Se ha emitido una nueva alerta en la plataforma AdOrbit correspondiente al evento <strong>${tipo}</strong>.</p>\n` +
    `    <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:16px 0;background:#f8fafc;border-radius:8px;overflow:hidden;">\n` +
    `      ${filasHtml || '<tr><td style="padding:10px;">Sin parámetros adicionales</td></tr>'}\n` +
    `    </table>\n` +
    `    <div style="text-align:center;margin:24px 0 12px 0;">\n` +
    `      <a href="${enlace}" style="display:inline-block;background:#4f46e5;color:#ffffff;text-decoration:none;font-weight:600;font-size:14px;padding:10px 22px;border-radius:8px;box-shadow:0 4px 6px -1px rgba(79,70,229,0.2);">Abrir en AdOrbit</a>\n` +
    `    </div>\n` +
    `  </div>\n` +
    `  <div style="background:#f8fafc;padding:18px 26px;border-top:1px solid #e2e8f0;text-align:center;font-size:12px;color:#64748b;">\n` +
    `    <p style="margin:0 0 4px 0;font-weight:600;color:#334155;">AdOrbit · Plataforma Publicitaria y Gestión Multicanal</p>\n` +
    `    <p style="margin:0;font-size:11px;color:#94a3b8;">Mensaje generado automáticamente por el subsistema de automatización y notificaciones.</p>\n` +
    `  </div>\n` +
    `</div>\n` +
    `</div>`;

  return [{
    json: {
      ok: true,
      whatsapp: {
        telefono: tel,
        mensaje: msgWhatsapp,
        imagen: imgWhatsapp
      },
      email: {
        para: email,
        asunto: `AdOrbit [${tipo.toUpperCase()}]: ${tituloLimpio}`,
        html: htmlCorreo
      },
      respuesta: {
        ok: true,
        mensaje: 'Notificación multicanal recibida y enrutada',
        tipo,
        canales: ['whatsapp', 'email'],
        destinatarios: { whatsapp: tel, email },
        timestamp: new Date().toISOString()
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      ok: false,
      estado_http: 500,
      respuesta: { codigo: 'error_interno', mensaje: 'Fallo interno en n8n', detalle: String(e && e.message || e) }
    }
  }];
}
